template <typename T>
class BinaryTreeNode {
public:
    BinaryTreeNode(T val) : data(val){}

    T data;
    BinaryTreeNode<T>* left {nullptr};
    BinaryTreeNode<T>* right {nullptr};
};

void add_left_child(BinaryTreeNode<T>* node) {
    left = node;
}

void add_right_child(BinaryTreeNode<T>* node) {
    right = node;
}
